import { docker, DockerError, type Run } from "./run";

/*
 * Starting and managing database containers. Every name and value that
 * reaches the shell is either generated by Warden or checked against a strict
 * pattern here, and quoted. Secrets never appear in a command: they go to the
 * server over stdin (writePrivateFile) and into the container via --env-file.
 */

const NAME = /^[a-z0-9][a-z0-9_.-]{0,62}$/;
const IMAGE = /^[a-z0-9][a-z0-9._/-]*:[A-Za-z0-9._-]+$/;
const PATH = /^\/[A-Za-z0-9._/-]+$/;

function check(kind: string, value: string, pattern: RegExp): string {
  if (!pattern.test(value)) throw new DockerError("failed", `Refusing an unsafe ${kind}: ${JSON.stringify(value)}`);
  return value;
}

/** Single-quote for sh: 'it'"'"'s' style. */
export const q = (s: string) => `'${s.replace(/'/g, `'"'"'`)}'`;

/**
 * For every long-running container Warden starts. Docker's default json-file
 * driver never rotates, so a chatty app would grow its log until the disk is
 * full. 3 × 10 MB per container; Warden's own log store keeps the history.
 */
export const LOG_OPTS = "--log-driver json-file --log-opt max-size=10m --log-opt max-file=3";

/**
 * Create the network if it isn't there yet. Containers on it reach each other
 * by name. Two databases created at once in a new environment both try to
 * create it: the one that loses gets "already exists", which is fine, so a
 * failed create counts if the network is there afterwards.
 */
export async function ensureNetwork(run: Run, name: string): Promise<void> {
  await docker(run, ensureNetworkCommand(name));
}

/** The command ensureNetwork runs, for scripts that run outside Warden (the EC2 installer). */
export function ensureNetworkCommand(name: string): string {
  const n = q(check("network name", name, NAME));
  return `docker network inspect ${n} >/dev/null 2>&1 || docker network create --label warden=1 ${n} || docker network inspect ${n} >/dev/null 2>&1`;
}

/** Create the volume (a no-op when it exists). The data lives here, not in the container. */
export async function ensureVolume(run: Run, name: string): Promise<void> {
  await docker(run, ensureVolumeCommand(name));
}

export function ensureVolumeCommand(name: string): string {
  return `docker volume create --label warden=1 ${q(check("volume name", name, NAME))}`;
}

/**
 * Write `content` to `path` readable only by the SSH user. The content goes
 * over stdin, so it never shows in the command, `ps` or shell history.
 */
export async function writePrivateFile(run: Run, path: string, content: string): Promise<void> {
  const r = await run(`umask 077 && cat > ${q(check("path", path, PATH))}`, content);
  if (r.code !== 0) throw new DockerError("failed", r.stderr.trim().split("\n")[0] || "couldn't write the file");
}

export async function removeFile(run: Run, path: string): Promise<void> {
  await run(`rm -f ${q(check("path", path, PATH))}`);
}

export interface ContainerSpec {
  name: string;
  image: string;
  network: string;
  volume: string;
  /** Where the volume is mounted inside the container. */
  dataPath: string;
  /** A file on the server with KEY=value lines (see writePrivateFile). */
  envFile: string;
  /** Run inside the container by `sh`, so it can use the container's own env vars. */
  healthCmd: string;
  /** Overrides the image's command, e.g. Redis needs its password passed in. */
  command?: string[];
  labels: Record<string, string>;
}

/**
 * `docker run -d …`. Deliberately has NO -p: the database is only reachable
 * on its private network. Restarts itself after a crash or reboot.
 */
export function runCommand(s: ContainerSpec): string {
  const labels = Object.entries(s.labels).map(([k, v]) => `--label ${q(`${check("label", k, /^[a-z0-9.]+$/)}=${check("label value", v, NAME)}`)}`);
  return [
    "docker run -d",
    `--name ${q(check("container name", s.name, NAME))}`,
    `--network ${q(check("network name", s.network, NAME))}`,
    "--restart unless-stopped",
    LOG_OPTS,
    `-v ${q(`${check("volume name", s.volume, NAME)}:${check("data path", s.dataPath, PATH)}`)}`,
    `--env-file ${q(check("env file", s.envFile, PATH))}`,
    ...labels,
    `--health-cmd ${q(s.healthCmd)}`,
    "--health-interval 5s --health-timeout 5s --health-retries 10 --health-start-period 30s",
    q(check("image", s.image, IMAGE)),
    ...(s.command ?? []).map(q),
  ].join(" ");
}

/** Download the image (a no-op when the server already has it). */
export async function pullImage(run: Run, image: string): Promise<void> {
  await docker(run, `docker pull -q ${q(check("image", image, IMAGE))}`);
}

export async function runContainer(run: Run, spec: ContainerSpec): Promise<void> {
  await docker(run, runCommand(spec));
}

export type HealthState = "starting" | "healthy" | "unhealthy" | "missing";

/** What Docker's health check says right now. */
export async function healthStatus(run: Run, name: string): Promise<HealthState> {
  const r = await run(`docker inspect --format '{{.State.Health.Status}}' ${q(check("container name", name, NAME))}`);
  if (r.code !== 0) return "missing";
  const s = r.stdout.trim();
  return s === "healthy" || s === "unhealthy" || s === "starting" ? s : "starting";
}

/**
 * Poll until healthy (resolves), unhealthy or gone (throws), or out of time.
 * MySQL's first boot on a 1 GB server can take well over a minute.
 */
export async function waitHealthy(run: Run, name: string, opts: { timeoutMs?: number; everyMs?: number; onPoll?: (s: HealthState) => void } = {}): Promise<void> {
  const deadline = Date.now() + (opts.timeoutMs ?? 150_000);
  for (;;) {
    const s = await healthStatus(run, name);
    opts.onPoll?.(s);
    if (s === "healthy") return;
    if (s === "unhealthy") throw new DockerError("failed", "The database started but failed its health check");
    if (s === "missing") throw new DockerError("failed", "The container stopped (check its logs on the server)");
    if (Date.now() > deadline) throw new DockerError("failed", "The database didn't become healthy in time");
    await new Promise((r) => setTimeout(r, opts.everyMs ?? 3000));
  }
}

/** The last lines the container printed: the usual reason a database won't start. */
export async function containerLogTail(run: Run, name: string, lines = 15): Promise<string> {
  const r = await run(`docker logs --tail ${lines} ${q(check("container name", name, NAME))} 2>&1`);
  return r.stdout.trim();
}

/** Was the container created with LOG_OPTS? Log settings only apply when a container is created. */
export async function logRotated(run: Run, name: string): Promise<boolean> {
  const r = await run(`docker inspect -f '{{index .HostConfig.LogConfig.Config "max-size"}}' ${q(check("container name", name, NAME))}`);
  return r.code === 0 && r.stdout.trim() !== "" && r.stdout.trim() !== "<no value>";
}

/**
 * A byte pipe to the database's port inside its own container: the data
 * browser runs a real driver over this, so nothing is ever published. Bash's
 * /dev/tcp opens the connection; two `cat`s copy each way, and whichever side
 * ends first (Warden closing stdin, or the database closing the socket) stops
 * both. fd 4 keeps the real stdin: bash gives background commands /dev/null.
 *
 * The final `wait` matters: bash must reap the cats itself. A process that
 * outlives its parent is handed to the container's PID 1, which in the
 * Postgres image is Postgres; it treats an unknown child dying of a signal as
 * a crash and restarts, dropping every connection (seen in testing).
 */
export function bridgeCommand(container: string, port: number): string {
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new DockerError("failed", `Refusing an unsafe port: ${port}`);
  const inner = `exec 4<&0 3<>/dev/tcp/127.0.0.1/${port}; cat <&3 & a=$!; cat <&4 >&3 & b=$!; wait -n; kill $a $b 2>/dev/null; wait`;
  return `docker exec -i ${q(check("container name", container, NAME))} bash -c ${q(inner)}`;
}

export async function restartContainer(run: Run, name: string): Promise<void> {
  await docker(run, `docker restart ${q(check("container name", name, NAME))}`);
}

/** Remove the container (fine if it's already gone). The volume, and so the data, stays. */
export async function removeContainer(run: Run, name: string): Promise<void> {
  await run(`docker rm -f ${q(check("container name", name, NAME))} >/dev/null 2>&1; true`);
}

/** Delete the volume, and with it all the data. Only when the user explicitly asked. */
export async function removeVolume(run: Run, name: string): Promise<void> {
  const r = await run(`docker volume rm ${q(check("volume name", name, NAME))} 2>&1`);
  if (r.code !== 0 && !/no such volume/i.test(r.stdout + r.stderr)) {
    throw new DockerError("failed", (r.stdout + r.stderr).trim().split("\n")[0] || "couldn't remove the volume");
  }
}
